/* Focused UI repairs; original story text and branch outcomes are retained. */
(()=>{'use strict';
 const notice=document.createElement('aside');notice.id='save-notice';notice.setAttribute('role','status');notice.style.cssText='padding:12px 20px;background:#fae8bd;border-bottom:1px solid #b09665';document.querySelector('.hud').before(notice);
 function status(){notice.hidden=!['recovery','unavailable','temporary'].includes(saveSession.status);if(notice.hidden)return;notice.replaceChildren();const text=document.createElement('span');text.textContent=saveSession.status==='recovery'?'儲存檔損壞或版本未支援。原檔保留；你可以暫時繼續玩，或先下載備份再重設。':'進度將不會儲存。你仍可完成故事及下載行動卡。';notice.append(text);if(saveSession.status==='recovery'){const backup=document.createElement('button');backup.className='textbtn';backup.textContent='下載原儲存檔';backup.onclick=()=>{const url=URL.createObjectURL(new Blob([saveSession.raw],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='lost-found-save-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};const reset=document.createElement('button');reset.className='textbtn';reset.textContent='重設故事存檔';reset.onclick=window.resetFullDemo;notice.append(backup,reset)}}
 window.journeySaveStatus=status;status();
 const oldReset=window.confirmReset;window.confirmReset=function(){if(!demo){saveSession.status='ready';saveSession.raw=null}oldReset();status()};
 window.resetFullDemo=function(){modal('重新開始故事？','<p>只清除呢個瀏覽器嘅故事進度同打卡。獨立遊戲紀錄、聲音設定及已下載檔案會保留。</p><div class="actions">'+btn('保留進度','window.closeModal()','secondary')+btn('清除故事並重新開始','window.confirmReset()')+'</div>')};
 // The arcade remains optional. Reflex performance never resolves a bill.
 const finish=window.finishArcade;window.finishArcade=function(){const run=window.moneyJourneySnapshot?.()||window.legacyArcadeSnapshot?.();finish();if(new URLSearchParams(location.search).has('arcade')||!run)return;const actions=$('modal-body').querySelector('.actions');if(actions&&run.key){const b=document.createElement('button');b.className='btn green';b.textContent='返回帳單，查清金融決定';b.onclick=()=>window.arcadeText(run.key);actions.prepend(b)}};
 window.arcadeContinue=function(key){if(new URLSearchParams(location.search).has('arcade'))window.closeModal();else window.arcadeText(key)};
 const settle=window.settleSocial;window.settleSocial=function(k){if(s.social!=='promise'||s.socialSettled)return;settle(k)};
 const follow=window.chooseFollowup;window.chooseFollowup=function(k){if(s.followupDone)return;follow(k)};
 const connection=window.setConnection;window.setConnection=function(k){if(s.connection)return;connection(k)};
 const toggleKit=window.toggleKit;window.toggleKit=function(k){if(s.kitLocked)return notify('認領袋已帶到海濱；其他線索仍可喺案情簿重看。');toggleKit(k)};
 // Repair the same clue when returning via a different UI: it costs time only once.
 const resolve=window.resolveClue;window.resolveClue=function(k,i){if(!evidence[k]||s.clues.includes(k))return;resolve(k,i)};
 const accept=window.acceptBudget;window.acceptBudget=function(){if(s.stage!==4||s.budgetStep<2)return;accept()};
 const journal=window.openJournal;window.openJournal=function(){journal();if(s.clues.includes('phone'))$('modal-body').insertAdjacentHTML('afterbegin','<p class="subtle">今日可用現金 $50；未收人工 $600 係預計收入，Day '+JourneyCore.project(s).payday+' 才放入試算。七日表係計劃，唔係已完成交易。</p>')};
 const renderBefore=render;render=function(focus=false){renderBefore(focus);status();if(s.stage===4&&s.budgetDone){const p=JourneyCore.project(s);$('app').insertAdjacentHTML('beforeend',`<aside class="response ${p.gapCents?'warn':'good'}" aria-label="故事預算摘要">故事試算：目前現金 $50；未到帳 $600。七日後預計 $${p.closingCents/100}。${p.gapCents?'尚有 $'+p.gapCents/100+' 時間性資金缺口，未確認支援前不可照表執行。':'已安排基本需要，冇時間性資金缺口。'}<button class="textbtn" onclick="window.fullBudget()">查看每日原因及付款日期</button></aside>`)}};
 // Separate frame and dialog keep optional range input, timers and credits isolated.
 let defence=null,defenceFocus=null;
 window.openBudgetDefence=function(){if(defence)return;defenceFocus=document.activeElement;defence=document.createElement('dialog');defence.id='budget-dialog';defence.setAttribute('aria-label','自選：預算防衛戰');defence.style.cssText='width:min(1120px,calc(100% - 16px));height:94dvh;max-height:94dvh;padding:0;background:#102724';const bar=document.createElement('div');bar.style.cssText='padding:8px 15px;background:#fff8ed;display:flex;justify-content:space-between;align-items:center;gap:10px';const label=document.createElement('strong');label.textContent='自選練習 · 唔影響主線';const close=document.createElement('button');close.className='textbtn';close.textContent='返回阿俊嘅故事 ✕';close.onclick=()=>defence.close();bar.append(label,close);const frame=document.createElement('iframe');frame.title='Budget Defence / 預算防衛戰';frame.src='../games/budget-defence/index.html';frame.style.cssText='display:block;width:100%;height:calc(100% - 56px);border:0';defence.append(bar,frame);document.body.append(defence);defence.addEventListener('close',()=>{defence?.remove();defence=null;defenceFocus?.isConnected&&defenceFocus.focus({preventScroll:true})},{once:true});defence.showModal();frame.focus()};
 window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===defence?.querySelector('iframe')?.contentWindow&&e.data?.type==='budget-defence-exit')defence.close()});
 const renderCore=render;render=function(focus=false){renderCore(focus);const locks=['先打開失物箱','整理四件線索，再完成或略過凌晨紀錄','聽兩個人、解一個帳單疑點、回覆群組，再帶兩件實物出發','完成海濱對話，再由阿俊選擇下一步'];document.querySelectorAll('#chapters button').forEach((b,i)=>{if(b.disabled)b.title='解鎖：'+locks[i]});if(s.started&&s.unlocked<4)$('app').insertAdjacentHTML('beforeend','<p class="subtle">下一幕解鎖：'+locks[s.unlocked]+'。</p>');if(s.started&&s.stage===2)$('app').insertAdjacentHTML('beforeend','<aside class="surface" style="margin-top:28px"><div class="kicker">自選練習 ／ 可以跳過</div><h3>預算防衛戰 / Budget Defence</h3><p class="subtle">阿俊嘅帳單之外，練習拒絕可疑優惠、保護必要交易、先查資料。三輪器材共用預算，唔會加減阿俊嘅錢，亦唔會代你解開帳單疑點。</p><div class="actions"><button class="btn secondary" onclick="window.openBudgetDefence()">進入自選訓練場</button></div></aside>')};
 render();
})();
